package za.co.loopmanager.preview;
import android.graphics.Bitmap;import android.graphics.Canvas;import android.view.View;import java.io.File;import java.io.FileOutputStream;import org.junit.Test;import org.junit.runner.RunWith;import org.robolectric.Robolectric;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import org.robolectric.annotation.GraphicsMode;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,qualifiers="w393dp-h851dp-xxhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class HomeScreenshotTest {
 @Test public void renderHome() throws Exception {MainActivity activity=Robolectric.buildActivity(MainActivity.class).setup().visible().get();View decor=activity.getWindow().getDecorView();decor.measure(View.MeasureSpec.makeMeasureSpec(1179,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(2553,View.MeasureSpec.EXACTLY));decor.layout(0,0,1179,2553);Bitmap bitmap=Bitmap.createBitmap(1179,2553,Bitmap.Config.ARGB_8888);decor.draw(new Canvas(bitmap));File out=new File("/workspace/loop-phone-manager/artifacts/bacy-customer-native.png");out.getParentFile().mkdirs();try(FileOutputStream stream=new FileOutputStream(out)){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}org.junit.Assert.assertTrue(out.length()>20000);}
 @Test public void renderVerifiedProgress() throws Exception {
  MainActivity activity=Robolectric.buildActivity(MainActivity.class).setup().visible().get();
  za.co.bacy.ui.CustomerHome.Model model=new za.co.bacy.ui.CustomerHome.Model();model.name="Test account";model.device="Loop test handset";model.reference="QA-ACCOUNT";model.status="Account connected";model.monthlyPayment="R300";model.due="Verified due date";model.remaining="30";model.paidTotal="R300";model.totalPrice="R900";model.approvedPayments=1;model.progressPercent=33.333f;
  activity.setContentView(za.co.bacy.ui.CustomerHome.create(activity,model,index->{}));View decor=activity.getWindow().getDecorView();decor.measure(View.MeasureSpec.makeMeasureSpec(1179,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(2553,View.MeasureSpec.EXACTLY));decor.layout(0,0,1179,2553);java.util.ArrayList<View> progress=new java.util.ArrayList<>();decor.findViewsWithText(progress,"33 percent repaid",View.FIND_VIEWS_WITH_CONTENT_DESCRIPTION);org.junit.Assert.assertEquals(1,progress.size());assertNavigationVisible(decor);View countdown=decor.findViewWithTag("account_countdown");org.junit.Assert.assertNotNull(countdown);org.junit.Assert.assertTrue(((android.widget.TextView)countdown).getText().toString().contains("30 days left"));android.graphics.Rect timeBounds=new android.graphics.Rect();org.junit.Assert.assertTrue(countdown.getGlobalVisibleRect(timeBounds));
  Bitmap bitmap=Bitmap.createBitmap(1179,2553,Bitmap.Config.ARGB_8888);decor.draw(new Canvas(bitmap));try(FileOutputStream stream=new FileOutputStream("/workspace/loop-phone-manager/artifacts/loop-customer-progress-qa.png")){bitmap.compress(Bitmap.CompressFormat.PNG,100,stream);}
 }
 private void assertNavigationVisible(View decor){for(String name:new String[]{"Home","Payments","Banking","Support"}){java.util.ArrayList<View> found=new java.util.ArrayList<>();decor.findViewsWithText(found,name,View.FIND_VIEWS_WITH_CONTENT_DESCRIPTION);found.removeIf(item->!name.contentEquals(item.getContentDescription())&&!(name+", current screen").contentEquals(item.getContentDescription()));org.junit.Assert.assertEquals(name,1,found.size());android.graphics.Rect bounds=new android.graphics.Rect();View item=found.get(0);org.junit.Assert.assertTrue(name,item.getGlobalVisibleRect(bounds));org.junit.Assert.assertEquals(name+" full width",item.getWidth(),bounds.width());}}
}
